/* Growing film-photo constellation inspired by the supplied motion reference. */
(()=>{'use strict';const entry=document.getElementById('entry');if(!entry)return;
const canvas=document.createElement('canvas');canvas.className='journey-canvas';canvas.setAttribute('aria-hidden','true');entry.prepend(canvas);const ctx=canvas.getContext('2d');let photos=[],last=0,time=0,previous=0,wasClosed=true;const nodes=[];
const roots=[[-.43,-.35],[-.34,.02],[-.42,.37],[.42,-.34],[.36,.04],[.43,.37],[-.1,-.43],[.13,.44]];
for(let i=0;i<26;i++){const group=i%8,ring=Math.floor(i/8),a=i*2.399,root=roots[group];nodes.push({x:root[0]+Math.cos(a)*ring*.045,y:root[1]+Math.sin(a)*ring*.065,size:44+(i%3)*10,image:i,parent:i<8?-1:group,birth:i*.17,phase:i*1.73})}
for(let i=0;i<156;i++){const parent=i%26,p=nodes[parent],a=i*2.399,r=.035+(i%6)*.012;nodes.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r*1.3,size:9+(i%4)*4,image:(i*7+parent)%26,parent,birth:1.4+(i%26)*.17+(i%6)*.24,phase:i*2.13})}
fetch('assets/journey/manifest.json').then(r=>r.json()).then(async films=>{photos=await Promise.all(films.map(f=>new Promise(resolve=>{const im=new Image();im.onload=()=>{const thumb=document.createElement('canvas');thumb.width=112;thumb.height=140;const c=thumb.getContext('2d'),s=Math.max(112/im.width,140/im.height),sw=112/s,sh=140/s;c.filter='sepia(.34) saturate(.48)';c.drawImage(im,(im.width-sw)/2,(im.height-sh)*.2,sw,sh,0,0,112,140);resolve(thumb)};im.onerror=()=>resolve(null);im.src=f.src})));entry.classList.add('journey-ready')}).catch(()=>{});
const ease=x=>1-Math.pow(1-Math.max(0,Math.min(1,x)),3);
function frame(now){requestAnimationFrame(frame);if(document.hidden||entry.hidden||entry.classList.contains('out')){previous=now;wasClosed=true;return}if(now-last<42)return;last=now;if(wasClosed){time=0;wasClosed=false}const reduced=document.body.classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced)time+=Math.min((now-(previous||now))/1000,.1);previous=now;if(!photos.length)return;
const w=entry.clientWidth,h=entry.clientHeight,dpr=Math.min(devicePixelRatio,1.5);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const t=reduced?12:time,zoom=1.1-.1*ease(t/16),sizeScale=Math.max(.58,Math.min(w/1100,1.25));
const positions=nodes.map(n=>({x:w*.5+(n.x*w+Math.sin(t*.14+n.phase)*7)*zoom,y:h*.5+(n.y*h+Math.cos(t*.12+n.phase)*6)*zoom,alpha:ease((t-n.birth)/1.6)}));
nodes.forEach((n,i)=>{const p=positions[i];if(!p.alpha)return;const parent=n.parent<0?(i?positions[i-1]:null):positions[n.parent];if(!parent)return;ctx.strokeStyle=`rgba(123,91,66,${.26*p.alpha})`;ctx.lineWidth=n.size>30?.65:.4;ctx.beginPath();ctx.moveTo(parent.x,parent.y);const ex=parent.x+(p.x-parent.x)*p.alpha,ey=parent.y+(p.y-parent.y)*p.alpha;ctx.quadraticCurveTo((parent.x+ex)/2+8,(parent.y+ey)/2-7,ex,ey);ctx.stroke();if(!reduced){const q=(t*.075+n.phase)%1;ctx.fillStyle=`rgba(174,105,63,${.36*p.alpha})`;ctx.beginPath();ctx.arc(parent.x+(p.x-parent.x)*q,parent.y+(p.y-parent.y)*q,1.2,0,Math.PI*2);ctx.fill()}});
nodes.forEach((n,i)=>{const p=positions[i],im=photos[n.image%photos.length];if(!im||!p.alpha)return;const s=n.size*sizeScale*(.72+.28*p.alpha),hh=s*1.25;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(n.phase)*.06+Math.sin(t*.08+n.phase)*.012);ctx.globalAlpha=p.alpha*(n.size>30?.76:.46);ctx.shadowColor='rgba(80,58,37,.15)';ctx.shadowBlur=n.size>30?9:3;ctx.fillStyle='#faf4e9';ctx.fillRect(-s/2-2,-hh/2-2,s+4,hh+4);ctx.shadowBlur=0;ctx.drawImage(im,-s/2,-hh/2,s,hh);ctx.restore()});
}requestAnimationFrame(frame);
})();
